/* xx_twrx_extractor.c - search raw data for TWRX.
 *
 * Scans for:
 *   54 57 52 58 00 01 00 00 at +0  ("TWRX....")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the twrx reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/twrx/xx_twrx.h"

static const uint8_t k_anchor0[] = { 0x54, 0x57, 0x52, 0x58, 0x00, 0x01, 0x00, 0x00 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_TWRX };

static Abstractformat *xx_twrx_search_open(xx_io_device *window) {
    xx_twrx *reader = xx_twrx_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_twrx_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_twrx_free((xx_twrx *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_twrx_search_open, xx_twrx_search_close
};

static xx_format_search_state *xx_twrx_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_twrx_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_twrx_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_twrx_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_twrx_extractor = {
    xx_twrx_create_format_search,
    xx_twrx_get_current_format_info,
    xx_twrx_format_search_find_next,
    xx_twrx_free_format_search
};
